/**
 * NFL Anytime TD V2 API
 *
 * Default: serves static JSON generated by scheduled workflow
 * Optional refresh: regenerates JSON on-demand (requires ODDS_API_KEY env var)
 *
 * IMPORTANT: ODDS_API_KEY must be provided via Netlify env var.
 * Never commit secrets into repo.
 */

import { execSync } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

export default async (req, context) => {
  const headers = {
    'Content-Type': 'application/json',
    'Cache-Control': 'public, max-age=60',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Access-Control-Allow-Methods': 'GET, OPTIONS'
  };

  try {
    if (req.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers });
    }

    const url = new URL(req.url);
    const isRefreshRequest = url.searchParams.get('refresh') === '1';

    if (isRefreshRequest) {
      if (!process.env.ODDS_API_KEY) {
        return new Response(
          JSON.stringify({
            error: 'Refresh not available - ODDS_API_KEY not configured',
            picks: []
          }),
          { status: 403, headers }
        );
      }

      try {
        // Run generator (writes to public/data/nfl/nfl-anytime-td-v2-live.json)
        execSync('python3 models/nfl_anytime_td/scripts/17_generate_live_json_v2.py', {
          cwd: process.cwd(),
          env: { ...process.env },
          stdio: 'inherit',
          timeout: 180000
        });
      } catch (error) {
        return new Response(
          JSON.stringify({
            error: 'Failed to refresh predictions',
            message: error.message,
            picks: []
          }),
          { status: 500, headers }
        );
      }
    }

    const jsonPath = join(process.cwd(), 'public/data/nfl/nfl-anytime-td-v2-live.json');

    if (!existsSync(jsonPath)) {
      return new Response(
        JSON.stringify({
          error: 'Predictions not yet generated',
          message: 'Daily workflow has not produced the file yet',
          picks: []
        }),
        { status: 404, headers }
      );
    }

    const data = readFileSync(jsonPath, 'utf-8');
    return new Response(data, { status: 200, headers });
  } catch (error) {
    return new Response(
      JSON.stringify({
        error: 'Failed to load predictions',
        message: error.message,
        picks: []
      }),
      { status: 500, headers }
    );
  }
};

export const config = {
  path: '/api/nfl-anytime-td-v2'
};
